 l jsonb; q jsonb; o jsonb; mid uuid; sid uuid; qid uuid; opt uuid;
BEGIN
 SELECT id INTO STRICT mid FROM public.modules WHERE code='M07';
 IF (SELECT count(*) FROM public.questions WHERE source_reference like 'Scratch-LOGO-2026-v3:%') NOT IN (0,60) THEN
  RAISE EXCEPTION 'Unexpected partial V3 question bank. Refusing import.';
 END IF;
 FOR l IN SELECT value FROM jsonb_array_elements(d->'lessons') LOOP
  INSERT INTO public.lessons(id,module_id,order_idx,slug,title_uz,body_mdx,est_minutes,status,blocks,topic_test_question_count)
  VALUES((l->>'id')::uuid,mid,(l->>'order_idx')::integer,lower(l->>'code'),l->>'title',l->>'body_md',45,'draft'::public.content_status,'[]'::jsonb,30)
  ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.lesson_constructs(lesson_id,construct_id,is_required,is_critical,min_questions)
  VALUES((l->>'id')::uuid,(l->>'construct_id')::uuid,true,false,1)
  ON CONFLICT (lesson_id,construct_id) DO NOTHING;
 END LOOP;
 FOR q IN SELECT value FROM jsonb_array_elements(d->'questions') LOOP
  qid:=(q->>'question_id')::uuid;
  INSERT INTO public.questions(id,subject_id,source_lesson_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference)
  SELECT qid,m.subject_id,(q->>'source_lesson_id')::uuid,(q->>'construct_id')::uuid,'S4.BLOCK',(q->>'format')::public.question_format,
    CASE WHEN (q->>'difficulty')::int <=2 THEN 'bilish'::public.cognitive_level
         WHEN (q->>'difficulty')::int <=4 THEN 'qollash'::public.cognitive_level
         ELSE 'mulohaza'::public.cognitive_level END,
    (q->>'difficulty')::integer,q->>'stem',coalesce(q->'assets','[]'::jsonb),false,'review'::public.content_status,
    'Scratch-LOGO-2026-v3:'||(q->>'id')||'; source='||(q->>'source')||'; topic='||(q->>'subtopic')
  FROM public.modules m WHERE m.id=mid
  ON CONFLICT(id) DO NOTHING;
  FOR o IN SELECT value FROM jsonb_array_elements(q->'options') LOOP
   INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
   VALUES((o->>'id')::uuid,qid,(o->>'side')::char,(o->>'order_idx')::int,o->>'content_md')
   ON CONFLICT(id) DO NOTHING;
  END LOOP;
  INSERT INTO public.question_keys(question_id,payload,explanation_md)
  VALUES(qid,q->'payload',q->>'why') ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
END $migration$;